mapper.select:
SELECT id, display_name AS displayName, tenant_status AS status, expires_at AS expiresAt,
       created_at AS createdAt, updated_at AS updatedAt
FROM tenants WHERE id = #{tenantId}

SELECT  FROM tenant_lifecycle_workflows
WHERE tenant_id = #{tenantId}
ORDER BY created_at DESC, workflow_id DESC LIMIT 1

mapper.update:
UPDATE tenant_lifecycle_workflows SET revocation_call_started = TRUE
WHERE workflow_id = #{workflowId} AND workflow_status = 'PENDING'
  AND fencing_token = #{fencingToken}

UPDATE tenant_lifecycle_workflows SET fence_established = TRUE, revocation_call_started = TRUE
WHERE workflow_id = #{workflowId} AND workflow_status = 'PENDING'
  AND fencing_token = #{fencingToken}

UPDATE tenant_lifecycle_workflows SET iam_recovery_confirmed_at = #{at}
WHERE workflow_id = #{workflowId} AND workflow_status = 'PENDING'
  AND recovery_started_at IS NOT NULL AND fencing_token = #{fencingToken}

UPDATE tenant_lifecycle_workflows
SET fence_established = fence_established OR #{fenceMayExist},
    revocation_call_started = CASE WHEN #{fenceMayExist} THEN TRUE ELSE FALSE END,
    workflow_status = CASE
        WHEN lifecycle_action IN ('SUSPEND', 'CLOSE') AND attempt_count >= #{maximumAttempts}
            THEN CASE WHEN fence_established OR #{fenceMayExist}
                      THEN 'RECOVERY_REQUIRED' ELSE 'RETRY_REQUIRED' END
        ELSE 'PENDING' END,
    recovery_exhausted_at = CASE
        WHEN lifecycle_action IN ('SUSPEND', 'CLOSE') AND attempt_count >= #{maximumAttempts} THEN #{at}
        ELSE recovery_exhausted_at END,
    next_attempt_at = #{retryAt}, lease_owner = NULL, lease_until = NULL, last_failure = #{failure}
WHERE workflow_id = #{workflowId} AND workflow_status = 'PENDING'
  AND fencing_token = #{fencingToken}

mapper.select:
SELECT workflow_id AS workflowId, request_fingerprint AS requestFingerprint
FROM tenant_suspension_recovery_idempotency
WHERE actor_identity_id = #{actorIdentityId} AND idempotency_key = #{idempotencyKey}

mapper.update:
UPDATE tenant_suspension_recovery_idempotency
SET response_body = CAST(#{responseBody} AS JSONB), completed_at = #{at}
WHERE workflow_id = #{workflowId} AND completed_at IS NULL
